const atelier=document.querySelector('#atelier'),mobileCta=document.querySelector('.mobile-cta');
document.querySelectorAll('[data-open-tab]').forEach(link=>link.addEventListener('click',()=>document.querySelector('#tab-'+link.dataset.openTab)?.click()));
let atelierActive=false,studioActive=false;
function mobileAction(){mobileCta.hidden=atelierActive;mobileCta.firstChild.textContent=studioActive?'İşletmem için web sitesi ':'911’ini tasarla ';mobileCta.href=studioActive?'https://u-luksstudyo.com':'#atelier';if(studioActive){mobileCta.target='_blank';mobileCta.rel='noopener';}else{mobileCta.removeAttribute('target');}}
if('IntersectionObserver'in window){new IntersectionObserver(entries=>{for(const e of entries){atelierActive=e.isIntersecting;document.querySelector('.atelier-layout').classList.toggle('atelier-active',atelierActive);mobileAction();}},{rootMargin:'-20% 0px -20% 0px'}).observe(atelier);new IntersectionObserver(entries=>{studioActive=entries[0].isIntersecting;mobileAction();},{threshold:.15}).observe(document.querySelector('#studio'));}

const expandButton=document.querySelector('#expand-atelier'),closeButton=document.querySelector('#close-atelier'),toolbar=document.querySelector('.expanded-toolbar'),optionsButton=document.querySelector('#toggle-options');let expanded=false,oldOverflow='';
function setExpanded(open){expanded=open;atelier.classList.toggle('atelier-expanded',open);expandButton.setAttribute('aria-expanded',String(open));toolbar.hidden=!open;if(open){oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';atelier.scrollTop=0;closeButton.focus({preventScroll:true});mobileCta.hidden=true;}else{document.body.style.overflow=oldOverflow;atelier.classList.remove('options-hidden');optionsButton.textContent='Seçenekleri gizle';optionsButton.setAttribute('aria-expanded','true');expandButton.focus({preventScroll:true});mobileAction();}}
expandButton.addEventListener('click',()=>setExpanded(true));closeButton.addEventListener('click',()=>setExpanded(false));document.addEventListener('keydown',e=>{if(expanded&&e.key==='Escape'){e.preventDefault();setExpanded(false);}});optionsButton.addEventListener('click',()=>{const hidden=atelier.classList.toggle('options-hidden');optionsButton.textContent=hidden?'Seçenekleri göster':'Seçenekleri gizle';optionsButton.setAttribute('aria-expanded',String(!hidden));});
atelier.addEventListener('keydown',e=>{if(!expanded||e.key!=='Tab')return;const focusable=[...atelier.querySelectorAll('button:not([disabled]),a[href],input,[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}});
